<?php
require_once __DIR__.'/_common.php'; $adminTitle='Vehicle Fitness'; $rows=$pdo->query("SELECT b.id,b.bus_number,b.status,vc.condition_status,vc.notes,vc.reported_at,u.name driver FROM buses b LEFT JOIN vehicle_conditions vc ON vc.id=(SELECT v2.id FROM vehicle_conditions v2 WHERE v2.bus_id=b.id ORDER BY v2.reported_at DESC LIMIT 1) LEFT JOIN users u ON u.id=vc.driver_id ORDER BY CASE WHEN vc.condition_status='Maintenance Required' THEN 1 WHEN vc.condition_status='Needs Attention' THEN 2 ELSE 3 END,b.bus_number")->fetchAll(); require __DIR__.'/_layout.php';
?>
<div class="admin-page-head"><div><span class="admin-kicker">FLEET HEALTH</span><h2>Vehicle Fitness</h2><p>Latest driver condition reports for every bus.</p></div></div>
<section class="admin-panel"><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Bus</th><th>Service Status</th><th>Condition</th><th>Latest Report</th><th>Driver</th><th>Maintenance</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><strong><?= e($r['bus_number']) ?></strong></td><td><?= statusBadge($r['status']) ?></td><td><?= statusBadge($r['condition_status']??'Not reported') ?></td><td><?= e($r['reported_at']??'—') ?><small><?= e($r['notes']??'') ?></small></td><td><?= e($r['driver']??'—') ?></td><td><?php if(($r['condition_status']??'')==='Maintenance Required'): ?><span class="admin-alert-text">Maintenance required</span><?php elseif(($r['condition_status']??'')==='Needs Attention'): ?><span class="admin-alert-text">Needs attention</span><?php else: ?>OK<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php require __DIR__.'/_layout_end.php'; ?>
